std::string decoded_text;
std::shared_ptr<Node> current_node = root;
int bit_count = 0;
char byte;
while (bit_count < encoded_length) {
    if (infile.eof()) {
        break;
    }
    infile.read(&byte, 1);
    for (int i = 7; i >= 0; --i) {
        bool bit = (byte >> i) & 1;
        if (bit) {
            if (current_node->right) {
                current_node = current_node->right;
            } else {
                throw std::runtime_error("Invalid Huffman tree");
            }
        } else {
            if (current_node->left) {
                current_node = current_node->left;
            } else {
                throw std::runtime_error("Invalid Huffman tree");
            }
        }
        if (current_node->character != '\0') {
            decoded_text += current_node->character;
            current_node = root;
            bit_count++;
        }
        if (bit_count >= encoded_length) {
            break;
        }
    }
}
return decoded_text;

